const MODE = 'keys';
const PID = '31393214664f295f94dd86.76792605';
const TAG = 'l10n/PERSO-4470';
const out = [];
if (MODE === 'tags') {
  for (let p = 1; p <= 40; p++) {
    out.push({ json: { url: 'https://api.lokalise.com/api2/projects/' + PID + '/keys?limit=500&page=' + p + '&filter_archived=exclude' } });
  }
} else {
  for (let p = 1; p <= 2; p++) {
    out.push({ json: { url: 'https://api.lokalise.com/api2/projects/' + PID + '/keys?limit=500&page=' + p + '&filter_archived=exclude&include_translations=1&filter_translation_lang_ids=640,1056&filter_tags=' + encodeURIComponent(TAG) } });
  }
}
return out;

const res = $input.all();
const tags = {};
const keys = [];
let total = null;
const statuses = [];
for (const r of res) {
  const j = r.json || {};
  statuses.push(j.statusCode);
  const h = j.headers || {};
  if (h['x-pagination-total-count']) { total = parseInt(h['x-pagination-total-count'], 10); }
  const ks = (j.body && j.body.keys) ? j.body.keys : [];
  for (const k of ks) {
    for (const t of (k.tags || [])) { tags[t] = (tags[t] || 0) + 1; }
    const tr = {};
    for (const x of (k.translations || [])) { tr[x.language_iso] = { t: x.translation, rev: x.is_reviewed, mod: x.modified_at, by: x.modified_by_email }; }
    const n = k.key_name || {};
    keys.push({ id: k.key_id, name: (typeof n === 'string') ? n : (n.web || n.other || n.ios || n.android || ''), platforms: k.platforms, filenames: k.filenames, tags: k.tags, tr: tr });
  }
}
return [{ json: { total: total, fetched: keys.length, statuses: statuses, tags: tags, keys: (Object.keys(tags).length && keys[0] && keys[0].tr && Object.keys(keys[0].tr).length) ? keys : [] } }];
